def main():
    import sys
    # 读取所有输入数据
    input_data = sys.stdin.read().split()
    s = input_data[0]
    q = int(input_data[1])
    k = int(input_data[2])

    # 预处理：构造  s  中所有长度为  k  的子串集合
    substrSet = set()
    for i in range(len(s) - k + 1):
        substrSet.add(s[i:i+k])

    index = 3  # 后续数据的起始下标
    res = []
    for _ in range(q):
        t = input_data[index]
        index += 1
        # 若  t  长度小于  k ，则直接输出 "NO"
        if len(t) < k:
            res.append("NO")
        else:
            # 获取  t  的前  k  和后  k  子串
            pre = t[:k]
            suf = t[-k:]
            # 判断是否存在于  s  的子串集合中
            if pre in substrSet or suf in substrSet:
                res.append("YES")
            else:
                res.append("NO")
    # 输出所有结果
    sys.stdout.write("\n".join(res))

